import type { ComponentProps } from "@solidjs/web";
import { cn } from "~/lib/utils.ts";
import type { Component } from "solid-js";

import { omit } from "solid-js";

const Kbd: Component<ComponentProps<"kbd">> = (props) => {
  const others = omit(props, "class");
  return (
    <kbd
      data-slot="kbd"
      class={cn(
        "h-5 w-fit min-w-5 gap-1 rounded-sm bg-muted px-1 font-sans text-xs font-medium text-muted-foreground in-data-[slot=tooltip-content]:bg-background/20 in-data-[slot=tooltip-content]:text-background dark:in-data-[slot=tooltip-content]:bg-background/10 [&_svg:not([class*='size-'])]:size-3 pointer-events-none inline-flex select-none items-center justify-center",
        props.class,
      )}
      {...others}
    />
  );
};

const KbdGroup: Component<ComponentProps<"kbd">> = (props) => {
  const others = omit(props, "class");
  return (
    <kbd
      data-slot="kbd-group"
      class={cn("gap-1 inline-flex items-center", props.class)}
      {...others}
    />
  );
};

export { Kbd, KbdGroup };
